/**
 * HIGH-02 FIX: Webhook Auth Guard for Voice Provider
 * Validates shared secret header to prevent unauthorized call injection.
 * Supports Vapi, Retell, or custom voice providers.
 */
const headers = $json.headers || {};
const body = $json.body || {};

// Auth: Check shared secret
const expectedSecret = $env.VOICE_WEBHOOK_SECRET || '';
const providedSecret = headers['x-voice-secret'] || headers['x-webhook-secret'] || '';

if (expectedSecret && providedSecret !== expectedSecret) {
  console.log(JSON.stringify({
    level: 'WARN',
    event: 'VOICE_AUTH_FAILED',
    ip: headers['x-forwarded-for'] || 'unknown',
    ts: new Date().toISOString()
  }));
  return [{
    json: {
      _authFailed: true,
      _resp: { error: 'UNAUTHORIZED', message: 'Invalid webhook secret' }
    }
  }];
}

// Extract caller number safely
const callerNumber = body.message?.call?.customer?.number 
  || body.caller_number 
  || body.from 
  || '';

if (!callerNumber) {
  return [{
    json: {
      _authFailed: true,
      _resp: { error: 'MISSING_CALLER', message: 'No caller number provided' }
    }
  }];
}

return [{
  json: {
    _authFailed: false,
    callerNumber: callerNumber.replace(/[^0-9+]/g, ''),
    rawBody: body
  }
}];

const menuItems = $node["Fetch Grounded Menu (DB)"].all();
const categories = {};
menuItems.forEach(i => {
  const cat = i.json.category || 'Autres';
  if (!categories[cat]) categories[cat] = [];
  categories[cat].push(`${i.json.name} (${i.json.price}DZD)`);
});

let menuStr = '';
for (const [cat, items] of Object.entries(categories)) {
  menuStr += `\n### ${cat}\n- ${items.join('\n- ')}`;
}

const caller = $('Identify Caller (DB)').first()?.json || { name: 'Client' };

const systemPrompt = `Tu es Ralphé Voice, l'agent IA premium de prise de commande.\n\nCONTEXTURE :\n- Client : ${caller.name}\n- Menu Actuel : ${menuStr}\n\nDIRECTIVES :\n1. Accueil : Salue chaleureusement le client.\n2. Menu : Ne propose QUE les articles listés ci-dessus. Si un article est indisponible, excuse-toi.\n3. Clôture : Une fois la commande prise, récapitule les articles et utilise 'finalizeOrder'.\n4. Style : Sois efficace, courtois et utilise un ton naturel (Français/Darja possible).`;

return [{
  json: {
    assistantId: 'ralphe_voice_v1',
    dynamicSystemPrompt: systemPrompt,
    voice: { name: 'french-natural', speed: 1.05 },
    metadata: { 
      customerPhone: $node['B0 - Voice Auth Guard'].json.callerNumber, 
      platform: 'voice' 
    }
  }
}];
